package com.bitewise.controller;
import com.bitewise.dto.AnalyticsDtos.*; import com.bitewise.service.AnalyticsService; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/analytics") public class AnalyticsController {private final AnalyticsService s; public AnalyticsController(AnalyticsService s){this.s=s;} @GetMapping("/dashboard") public Dashboard dashboard(){return s.dashboard();} @GetMapping("/daily") public PeriodReport daily(@RequestParam LocalDate date){return s.report(date,date);} @GetMapping("/weekly") public PeriodReport weekly(@RequestParam(required=false) LocalDate end){LocalDate e=end==null?LocalDate.now():end;return s.report(e.minusDays(6),e);} @GetMapping("/monthly") public PeriodReport monthly(@RequestParam(required=false) Integer year,@RequestParam(required=false) Integer month){LocalDate now=LocalDate.now();int y=year==null?now.getYear():year,m=month==null?now.getMonthValue():month;LocalDate from=LocalDate.of(y,m,1),to=from.withDayOfMonth(from.lengthOfMonth());return s.report(from,to);} @GetMapping("/range") public PeriodReport range(@RequestParam LocalDate from,@RequestParam LocalDate to){return s.report(from,to);} }
